  4→
  5→type HomeProps = {
  6→    firstName: string;
  7→    avatar: string | null;
  8→};
  9→
 10→const actionCards = [
 11→    {
 12→        label: 'Ver estado de mi explotación',
 13→        icon: BarChart3,
 14→        href: '/dashboard',
 15→        disabled: false,
 16→    },
 17→    {
 18→        label: 'Consultar censo actual',
 19→        icon: Search,
 20→        href: '#',
 21→        disabled: true,
 22→    },
