 24→        label: 'Revisar alertas pendientes',
 25→        icon: TriangleAlert,
 26→        href: '/normativa',
 27→        disabled: false,
 28→    },
 29→    {
 30→        label: 'Iniciar un trámite',
 31→        icon: FileText,
 32→        href: '/nacimientos/crear',
 33→        disabled: false,
 34→    },
 35→];
 36→
 37→const quickActions = [
 38→    {
 39→        label: 'Ver estado de mi explotación',
 40→        icon: BarChart3,
 41→        href: '/dashboard',
 42→        disabled: false,
 43→    },
 44→    {
 45→        label: 'Consultar censo actual',
 46→        icon: Search,
 47→        href: '#',
 48→        disabled: true,
 49→    },
 50→    {
 51→        label: 'Revisar alertas pendientes',
