  1→import { Head, Link, router } from '@inertiajs/react';
  2→import { AlertTriangle, Bell, CheckCircle2, ChevronRight, Info, ShieldAlert, Syringe } from 'lucide-react';
  3→import { useState } from 'react';
  4→import AppLayout from '@/layouts/app-layout';
  5→import type { BreadcrumbItem } from '@/types';
  6→
  7→interface Regulation {
  8→    id: number;
  9→    type: string;
 10→    severity: 'urgent' | 'warning' | 'info';
 11→    title: string;
 12→    description: string;
 13→    action_label: string | null;
 14→    action_url: string | null;
 15→    due_date: string | null;
 16→    is_read: boolean;
 17→    is_resolved: boolean;
 18→    created_at: string;
 19→}
 20→
 21→interface Props {
 22→    regulations: Regulation[];
 23→}
 24→
 25→const breadcrumbs: BreadcrumbItem[] = [
 26→    { title: 'Mi Explotación', href: '/dashboard' },
 27→    { title: 'Normativa', href: '/normativa' },
 28→];
 29→
 30→const severityConfig = {
 31→    urgent: {
 32→        icon: ShieldAlert,
 33→        label: 'Urgente',
 34→        badgeBg: 'bg-[#E53935]',
 35→        badgeText: 'text-white',
 36→        borderColor: 'border-l-[#E53935]',
 37→        countBg: 'bg-[#E53935]',
 38→    },
 39→    warning: {
 40→        icon: AlertTriangle,
 41→        label: 'Atención',
 42→        badgeBg: 'bg-[#FFF3E0]',
 43→        badgeText: 'text-[#E65100]',
 44→        borderColor: 'border-l-[#E65100]',
 45→        countBg: 'bg-[#E65100]',
 46→    },
 47→    info: {
 48→        icon: Info,
 49→        label: 'Información',
 50→        badgeBg: 'bg-[#E3F2FD]',
 51→        badgeText: 'text-[#1565C0]',
 52→        borderColor: 'border-l-[#1565C0]',
 53→        countBg: 'bg-[#1565C0]',
 54→    },
 55→};
 56→
 57→function timeAgo(dateString: string): string {
 58→    const now = new Date();
 59→    const date = new Date(dateString);
 60→    const diffMs = now.getTime() - date.getTime();
 61→    const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
 62→    const diffDays = Math.floor(diffHours / 24);
 63→
 64→    if (diffHours < 1) return 'hace un momento';
 65→    if (diffHours < 24) return `hace ${diffHours}h`;
 66→    if (diffDays === 1) return 'ayer';
 67→    return `hace ${diffDays} días`;
 68→}
 69→
 70→function daysUntil(dateString: string): string | null {
 71→    const now = new Date();
 72→    const date = new Date(dateString);
 73→    const diffMs = date.getTime() - now.getTime();
 74→    const days = Math.ceil(diffMs / (1000 * 60 * 60 * 24));
 75→
 76→    if (days < 0) return 'Vencido';
 77→    if (days === 0) return 'Hoy';
 78→    if (days === 1) return 'Mañana';
 79→    return `Quedan ${days} días`;
 80→}
 81→
 82→function AlertCard({ regulation }: { regulation: Regulation }) {
 83→    const config = severityConfig[regulation.severity];
 84→    const Icon = config.icon;
 85→
 86→    const markResolved = () => {
 87→        router.post(`/api/regulations/${regulation.id}/resolve`, {}, { preserveScroll: true });
 88→    };
 89→
 90→    return (
 91→        <div
 92→            className={`border-2 border-black border-l-4 ${config.borderColor} ${!regulation.is_read ? 'bg-[#FAFAFA]' : 'bg-white'} w-full`}
 93→        >
 94→            <div className="flex flex-col gap-3 p-4">
 95→                <div className="flex items-center justify-between">
 96→                    <span className={`inline-flex items-center gap-1.5 px-2 py-0.5 text-xs font-bold ${config.badgeBg} ${config.badgeText}`}>
 97→                        <Icon className="size-3" />
 98→                        {config.label}
 99→                    </span>
100→                    <span className="text-xs text-[#757575]">{timeAgo(regulation.created_at)}</span>
101→                </div>
102→
103→                <h3 className="text-sm font-bold">{regulation.title}</h3>
104→                <p className="text-sm leading-[1.4] text-[#757575]">{regulation.description}</p>
105→
106→                {regulation.due_date && (
107→                    <p className="text-xs font-semibold text-[#757575]">
108→                        Vence: {new Date(regulation.due_date).toLocaleDateString('es-ES', { day: 'numeric', month: 'long', year: 'numeric' })}
109→                        {' · '}
110→                        <span className={regulation.severity === 'urgent' ? 'text-[#E53935]' : ''}>{daysUntil(regulation.due_date)}</span>
111→                    </p>
112→                )}
113→
114→                <div className="flex items-center gap-2">
115→                    {regulation.action_url && regulation.action_label && (
116→                        <Link
117→                            href={regulation.action_url}
118→                            className="inline-flex items-center gap-1 bg-[#E53935] px-3 min-h-[44px] text-xs font-bold text-white md:min-h-0 md:py-2"
119→                        >
120→                            {regulation.action_label}
121→                        </Link>
122→                    )}
123→                    {!regulation.is_resolved && (
124→                        <button
125→                            onClick={markResolved}
126→                            className="inline-flex items-center gap-1 border-2 border-black px-3 min-h-[44px] text-xs font-semibold md:min-h-0 md:py-2"
127→                        >
128→                            <CheckCircle2 className="size-3" />
129→                            Resolver
130→                        </button>
131→                    )}
132→                </div>
133→            </div>
134→        </div>
135→    );
136→}
137→
138→type Filter = 'all' | 'pending' | 'resolved';
139→
140→export default function NormativaIndex({ regulations }: Props) {
141→    const [filter, setFilter] = useState<Filter>('all');
142→
143→    const filtered = regulations.filter((r) => {
144→        if (filter === 'pending') return !r.is_resolved;
145→        if (filter === 'resolved') return r.is_resolved;
146→        return true;
147→    });
148→
149→    const urgentCount = regulations.filter((r) => r.severity === 'urgent' && !r.is_resolved).length;
150→    const warningCount = regulations.filter((r) => r.severity === 'warning' && !r.is_resolved).length;
151→    const infoCount = regulations.filter((r) => r.severity === 'info' && !r.is_resolved).length;
152→
153→    const filters: { key: Filter; label: string }[] = [
154→        { key: 'all', label: 'Todas' },
155→        { key: 'pending', label: 'Pendientes' },
156→        { key: 'resolved', label: 'Resueltas' },
157→    ];
158→
159→    return (
160→        <AppLayout breadcrumbs={breadcrumbs}>
161→            <Head title="Normativa" />
162→            <div className="flex flex-col gap-5 p-6">
163→                <h1 className="text-2xl font-bold">Mis Alertas y Normativa</h1>
164→
165→                <Link
166→                    href="/normativa/campanas"
167→                    className="flex items-center justify-between border-2 border-black bg-white p-4 active:bg-[#F5F5F5]"
168→                >
169→                    <div className="flex items-center gap-3">
170→                        <div className="flex size-10 items-center justify-center bg-[#FFEBEE]">
171→                            <Syringe className="size-5 text-[#E53935]" />
172→                        </div>
173→                        <div>
174→                            <p className="text-sm font-bold">Campañas Sanitarias</p>
175→                            <p className="text-xs text-[#757575]">Ver estado de campañas y animales inmovilizados</p>
176→                        </div>
177→                    </div>
178→                    <ChevronRight className="size-5 text-[#757575]" />
179→                </Link>
180→
181→                <div className="flex items-center gap-3">
182→                    {urgentCount > 0 && (
183→                        <span className="inline-flex items-center gap-1 bg-[#E53935] px-2 py-1 text-xs font-bold text-white">
184→                            {urgentCount} urgente{urgentCount > 1 ? 's' : ''}
185→                        </span>
186→                    )}
187→                    {warningCount > 0 && (
188→                        <span className="inline-flex items-center gap-1 bg-[#FFF3E0] px-2 py-1 text-xs font-bold text-[#E65100]">
189→                            {warningCount} atención
190→                        </span>
191→                    )}
192→                    {infoCount > 0 && (
193→                        <span className="inline-flex items-center gap-1 bg-[#E3F2FD] px-2 py-1 text-xs font-bold text-[#1565C0]">
194→                            {infoCount} info
195→                        </span>
196→                    )}
197→                </div>
198→
199→                <div className="flex gap-0 border-2 border-black">
200→                    {filters.map((f) => (
201→                        <button
202→                            key={f.key}
203→                            onClick={() => setFilter(f.key)}
204→                            className={`flex-1 min-h-[44px] text-xs font-bold md:min-h-0 md:py-2 ${filter === f.key ? 'bg-black text-white' : 'bg-white text-black'}`}
205→                        >
206→                            {f.label}
207→                        </button>
208→                    ))}
209→                </div>
210→
211→                {filtered.length === 0 ? (
212→                    <div className="flex flex-col items-center gap-3 py-16 text-center">
213→                        <CheckCircle2 className="size-12 text-[#2E7D32]" />
214→                        <p className="text-lg font-bold">Todo al día</p>
215→                        <p className="text-sm text-[#757575]">No tienes alertas pendientes. Te avisaremos cuando haya algo nuevo.</p>
216→                    </div>
217→                ) : (
218→                    <div className="flex flex-col gap-3">
219→                        {filtered.map((regulation) => (
220→                            <AlertCard key={regulation.id} regulation={regulation} />
221→                        ))}
222→                    </div>
223→                )}
224→            </div>
225→        </AppLayout>
226→    );
227→}
