 1→<?php
 2→
 3→namespace App\Http\Controllers;
 4→
 5→use App\Models\Regulation;
 6→use Illuminate\Http\Request;
 7→use Inertia\Inertia;
 8→use Inertia\Response;
 9→
10→class RegulationController extends Controller
11→{
12→    public function index(Request $request): Response
13→    {
14→        $exploitation = $request->user()->exploitations()->first();
15→
16→        $regulations = $exploitation
17→            ? Regulation::query()
18→                ->where('exploitation_id', $exploitation->id)
19→                ->orderByRaw("CASE severity WHEN 'urgent' THEN 1 WHEN 'warning' THEN 2 WHEN 'info' THEN 3 ELSE 4 END")
20→                ->latest()
21→                ->get()
22→            : collect();
23→
24→        $grouped = $regulations->groupBy('severity');
25→
26→        return Inertia::render('normativa/index', [
27→            'regulations' => $regulations,
28→            'grouped' => $grouped,
29→            'counts' => [
30→                'urgent' => $grouped->get('urgent')?->count() ?? 0,
31→                'warning' => $grouped->get('warning')?->count() ?? 0,
32→                'info' => $grouped->get('info')?->count() ?? 0,
33→            ],
34→        ]);
35→    }
36→}
