 1→<?php
 2→
 3→namespace App\Http\Controllers;
 4→
 5→use Illuminate\Http\Request;
 6→use Inertia\Inertia;
 7→use Inertia\Response;
 8→
 9→class DashboardController extends Controller
10→{
11→    public function index(Request $request): Response
12→    {
13→        $exploitation = $request->user()
14→            ->exploitations()
15→            ->with(['subExploitations' => function ($query) {
16→                $query->withCount('animals')->orderBy('species');
17→            }])
18→            ->first();
19→
20→        $unreadRegulationsCount = 0;
21→
22→        if ($exploitation) {
23→            $unreadRegulationsCount = $exploitation->regulations()
24→                ->where('is_read', false)
25→                ->count();
26→        }
27→
28→        return Inertia::render('dashboard', [
29→            'exploitation' => $exploitation,
30→            'unreadRegulationsCount' => $unreadRegulationsCount,
31→        ]);
32→    }
33→}
