 1→<?php
 2→
 3→namespace Database\Factories;
 4→
 5→use App\Models\Exploitation;
 6→use App\Models\Regulation;
 7→use Illuminate\Database\Eloquent\Factories\Factory;
 8→
 9→/**
10→ * @extends Factory<Regulation>
11→ */
12→class RegulationFactory extends Factory
13→{
14→    /**
15→     * Define the model's default state.
16→     *
17→     * @return array<string, mixed>
18→     */
19→    public function definition(): array
20→    {
