 5→use App\Models\ChatConversation;
 6→use App\Services\ChatbotService;
 7→use Illuminate\Http\JsonResponse;
 8→use Illuminate\Http\Request;
 9→use Inertia\Inertia;
10→use Inertia\Response;
11→
12→class ChatController extends Controller
13→{
14→    public function index(Request $request): Response
15→    {
16→        $conversation = ChatConversation::query()
17→            ->firstOrCreate(
18→                ['user_id' => $request->user()->id],
19→                [
20→                    'started_at' => now(),
21→                    'last_message_at' => now(),
22→                ],
23→            );
24→
25→        $conversation->load('messages');
26→
27→        return Inertia::render('chat/index', [
28→            'conversation' => $conversation,
29→            'messages' => $conversation->messages()->orderBy('created_at')->get(),
30→        ]);
31→    }
32→
33→    public function store(Request $request): JsonResponse
34→    {
35→        $request->validate([
36→            'message' => ['required', 'string', 'max:1000'],
37→        ]);
38→
39→        $user = $request->user();
40→
41→        $conversation = ChatConversation::query()
42→            ->firstOrCreate(
43→                ['user_id' => $user->id],
44→                [
45→                    'started_at' => now(),
46→                    'last_message_at' => now(),
47→                ],
48→            );
49→
50→        $conversation->messages()->create([
51→            'role' => 'user',
52→            'content' => $request->input('message'),
53→            'created_at' => now(),
54→        ]);
55→
56→        $chatbotService = new ChatbotService;
57→        $response = $chatbotService->respond($request->input('message'), $user);
58→
59→        $assistantMessage = $conversation->messages()->create([
60→            'role' => 'assistant',
61→            'content' => $response['content'],
62→            'quick_replies' => $response['quick_replies'],
63→            'created_at' => now(),
64→        ]);
65→
66→        $conversation->update(['last_message_at' => now()]);
67→
68→        return response()->json([
69→            'message' => $assistantMessage,
70→        ]);
71→    }
72→}
