  1→import { Head, usePage } from '@inertiajs/react';
  2→import { Bot, Send } from 'lucide-react';
  3→import { useEffect, useRef, useState } from 'react';
  4→import AppLayout from '@/layouts/app-layout';
  5→import type { BreadcrumbItem, SharedData } from '@/types';
  6→
  7→interface Message {
  8→    id: number;
  9→    role: 'user' | 'assistant';
 10→    content: string;
 11→    quick_replies: string[] | null;
 12→    created_at: string;
