 17→    messages: Message[];
 18→}
 19→
 20→interface Props {
 21→    conversation: Conversation;
 22→}
 23→
 24→const breadcrumbs: BreadcrumbItem[] = [
 25→    { title: 'Mi Explotación', href: '/dashboard' },
 26→    { title: 'NekazarIA Chat', href: '/chat' },
 27→];
 28→
 29→function TypingIndicator() {
 30→    return (
 31→        <div className="flex items-end gap-2">
 32→            <div className="flex size-8 shrink-0 items-center justify-center bg-[#E53935] text-white">
 33→                <Bot className="size-4" />
 34→            </div>
 35→            <div className="flex gap-1 bg-[#F5F5F5] px-4 py-3">
