 39→            </div>
 40→        </div>
 41→    );
 42→}
 43→
 44→function ChatBubble({ message }: { message: Message }) {
 45→    const isUser = message.role === 'user';
 46→
 47→    return (
 48→        <div className={`flex items-end gap-2 ${isUser ? 'flex-row-reverse' : ''}`}>
 49→            {!isUser && (
 50→                <div className="flex size-8 shrink-0 items-center justify-center bg-[#E53935] text-white">
 51→                    <Bot className="size-4" />
 52→                </div>
 53→            )}
 54→            <div className={`max-w-[80%] px-4 py-3 text-sm leading-[1.4] ${isUser ? 'bg-[#E53935] text-white' : 'bg-[#F5F5F5] text-black'}`}>
 55→                {message.content}
 56→            </div>
 57→        </div>
 58→    );
 59→}
