 61→export default function ChatIndex({ conversation }: Props) {
 62→    const { auth } = usePage<SharedData>().props;
 63→    const [messages, setMessages] = useState<Message[]>(conversation.messages || []);
 64→    const [input, setInput] = useState('');
 65→    const [typing, setTyping] = useState(false);
 66→    const scrollRef = useRef<HTMLDivElement>(null);
 67→    const inputRef = useRef<HTMLInputElement>(null);
 68→
 69→    useEffect(() => {
 70→        scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
 71→    }, [messages, typing]);
 72→
 73→    const sendMessage = async (text: string) => {
 74→        if (!text.trim()) return;
 75→        setInput('');
 76→
 77→        const userMsg: Message = {
 78→            id: Date.now(),
 79→            role: 'user',
 80→            content: text.trim(),
 81→            quick_replies: null,
 82→            created_at: new Date().toISOString(),
 83→        };
 84→        setMessages((prev) => [...prev, userMsg]);
 85→        setTyping(true);
 86→
 87→        try {
 88→            const res = await fetch('/chat/messages', {
 89→                method: 'POST',
 90→                headers: {
 91→                    'Content-Type': 'application/json',
 92→                    'X-CSRF-TOKEN': document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content || '',
 93→                    'Accept': 'application/json',
 94→                },
 95→                body: JSON.stringify({ message: text.trim() }),
 96→            });
 97→
 98→            if (res.ok) {
 99→                const data = await res.json();
100→                await new Promise((r) => setTimeout(r, 500 + Math.random() * 1000));
101→                setMessages((prev) => [...prev, data.message]);
102→            }
103→        } catch {
104→            setMessages((prev) => [...prev, {
105→                id: Date.now() + 1,
106→                role: 'assistant',
107→                content: 'Lo siento, ha ocurrido un error. Intenta de nuevo.',
108→                quick_replies: ['Ayuda'],
109→                created_at: new Date().toISOString(),
110→            }]);
111→        }
112→        setTyping(false);
113→        inputRef.current?.focus();
114→    };
115→
116→    const lastAssistantMsg = [...messages].reverse().find((m) => m.role === 'assistant');
117→
118→    return (
119→        <AppLayout breadcrumbs={breadcrumbs}>
120→            <Head title="NekazarIA Chat" />
121→            <div className="flex h-[calc(100vh-8rem)] flex-col">
122→                <div className="flex items-center gap-3 border-b-2 border-black px-4 py-3">
123→                    <div className="flex size-10 items-center justify-center bg-[#E53935] text-white">
124→                        <Bot className="size-5" />
125→                    </div>
126→                    <div>
127→                        <p className="text-sm font-bold">NekazarIA Laguntzailea</p>
128→                        <p className="text-xs text-[#2E7D32]">En línea</p>
129→                    </div>
130→                </div>
131→
132→                <div ref={scrollRef} className="flex-1 overflow-y-auto p-4">
133→                    <div className="flex flex-col gap-4">
134→                        {messages.length === 0 && (
135→                            <div className="flex flex-col items-center gap-3 py-8 text-center">
136→                                <div className="flex size-16 items-center justify-center bg-[#F5F5F5]">
137→                                    <Bot className="size-8 text-[#757575]" />
138→                                </div>
139→                                <p className="text-sm text-[#757575]">Escribe un mensaje o usa las opciones rápidas</p>
140→                            </div>
141→                        )}
142→
143→                        {messages.map((msg) => (
144→                            <ChatBubble key={msg.id} message={msg} />
145→                        ))}
146→
147→                        {typing && <TypingIndicator />}
148→                    </div>
149→                </div>
150→
151→                {lastAssistantMsg?.quick_replies && lastAssistantMsg.quick_replies.length > 0 && !typing && (
152→                    <div className="flex gap-2 overflow-x-auto border-t border-[#E0E0E0] px-4 py-2">
153→                        {lastAssistantMsg.quick_replies.map((reply) => (
154→                            <button
155→                                key={reply}
156→                                onClick={() => sendMessage(reply)}
157→                                className="shrink-0 border-2 border-black px-3 py-1.5 text-xs font-semibold hover:bg-[#F5F5F5]"
158→                            >
159→                                {reply}
160→                            </button>
161→                        ))}
162→                    </div>
163→                )}
164→
165→                <div className="flex items-center gap-2 border-t-2 border-black p-4">
166→                    <input
167→                        ref={inputRef}
168→                        type="text"
169→                        value={input}
170→                        onChange={(e) => setInput(e.target.value)}
171→                        onKeyDown={(e) => e.key === 'Enter' && sendMessage(input)}
172→                        placeholder="Escribe tu mensaje..."
173→                        className="h-[44px] flex-1 bg-[#F5F5F5] px-4 text-sm"
174→                    />
175→                    <button
176→                        onClick={() => sendMessage(input)}
177→                        disabled={!input.trim() || typing}
178→                        className="flex size-[44px] items-center justify-center bg-[#E53935] text-white disabled:opacity-50"
179→                    >
180→                        <Send className="size-5" />
181→                    </button>
182→                </div>
183→            </div>
184→        </AppLayout>
185→    );
186→}
